'use strict';
// Reproduce the reported creator combination; verify full-jaw and lip clearance, not only anchors.
window.RUN=async()=>{const {ok,exc,out}=Kit.report();try{const E=T.PortraitEngine,A=T.PortraitArtwork,C=T.PortraitCharacters;await A.ready;const read=c=>c.getContext('2d').getImageData(0,0,c.width,c.height).data,hoods=['hood','wrapped-hood','veil','draped-veil','pearl-hood'];let fits=0;
 for(const race of E.races)for(const profile of ['male','female'])for(const width of [-2,0,2])for(const headwear of hoods){const p=A.build({...E.startRace(race,E.startProfile(profile)),profile,headwear,beard:'none',adjustments:{faceWidth:width,jawWidth:width}},{size:128}),d=read(p.layers.headwearFront),a=p.anchors;for(const pt of [...a.eyes,a.mouth,{x:a.cx,y:a.chinY-1}])for(let dx=-2;dx<=2;dx++)if(d[(Math.floor(pt.y)*128+Math.floor(pt.x+dx))*4+3])throw Error('Hood crowds face or jaw: '+race+'/'+profile+'/'+headwear+'/'+width);if(p.headwearMaster.file!=='headwear-open-face.png')throw Error('Old tight hood master selected');fits++;}
 ok(fits===120,'all five redrawn hoods/veils leave eyes, mouth and full chin clear across eight profiles and narrow/wide faces');
 let lips=0;for(const race of ['human','dwarf'])for(const mouth of E.partsFor(race,'mouth'))for(const beard of ['moustache','walrus','goatee','full','scruffy']){const p=A.build({...E.startRace(race,E.startProfile('male')),profile:'male',mouth,beard,headwear:'none'},{size:128}),d=read(p.layers.beard),a=p.anchors;for(let dx=-2;dx<=2;dx++)if(d[(Math.floor(a.mouth.y)*128+Math.floor(a.mouth.x+dx))*4+3])throw Error('Beard covers mouth seam: '+race+'/'+mouth+'/'+beard);lips++;}
 ok(lips>100,'moustaches, goatees, full beards and scruff preserve the central lip seam for every human/dwarf mouth shape');
 let noses=new Set();for(const race of E.races)for(const profile of ['male','female','custom'])for(let seed=0;seed<64;seed++){const c=E.random(seed,profile,race);if(JSON.stringify(c)!==JSON.stringify(E.random(seed,profile,race)))throw Error('Random face is not deterministic');if(profile==='female'&&c.beard!=='none')throw Error('Unexpected generated facial hair');if(profile!=='female'&&['cupid','pout','soft-full'].includes(c.mouth))throw Error('Uncurated generated combination');if(race==='human')noses.add(c.nose);}
 ok(noses.size>5,'generated profiles stay coherent and deterministic while retaining broad nose variation');
 const manual=E.normalize({...E.startProfile('male'),mouth:'cupid',eyes:'upturned',beard:'moustache',headwear:'hood'});ok(manual.mouth==='cupid'&&manual.eyes==='upturned'&&manual.beard==='moustache','explicit manual facial choices are preserved');
 const orc=C.recipe({config:E.random(318,'male','orc')});ok(orc.colors.iris===C.palettes.orc.iris&&orc.colors.iris==='#bf983f','new orc defaults use the intended warm iris palette');
 const F=T.Faces,saved=F.draft;try{F.draft={race:'human',g:'m',rec:C.recipe({config:manual})};T.showPanel(F.maker('human','m'));const im=document.querySelector('.fm-portrait');await im.decode();const css=getComputedStyle(im),old=im.src;F.set('mouth','neutral');F.refresh();await im.decode();ok(css.maskImage==='none'&&css.filter==='none'&&!document.querySelector('.face-maker .fm-pic')&&im.src!==old,'creator preview is isolated from map CSS and live feature changes refresh its artwork');}finally{F.draft=saved;T.hidePanel()}
 }catch(e){exc(e)}finally{out()}};
